// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        c.addReward(address(this));

        address nonOwner = address(1);
        vm.prank(nonOwner);

        bool ok;
        try c.addReward(address(2)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Reference should revert when non-owner calls addReward");
    }
}
